package com.smarthealth.util;import java.security.*;import java.util.*;public final class PasswordUtil{private PasswordUtil(){}public static String salt(){byte[] b=new byte[16];new SecureRandom().nextBytes(b);return Base64.getEncoder().encodeToString(b);}public static String hash(String password,String salt){try{MessageDigest d=MessageDigest.getInstance("SHA-256");d.update(Base64.getDecoder().decode(salt));return Base64.getEncoder().encodeToString(d.digest(password.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public static boolean verify(String p,String s,String hash){return MessageDigest.isEqual(hash(p,s).getBytes(),hash.getBytes());}}
